// ──────────────────────────────────────────────────────────────────
// Helpers
// ──────────────────────────────────────────────────────────────────

function normalizeName(name: string): string {
  return name
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z]/g, "");
}

// Index by normalized name → list of (tournament, entry). Built lazily and
// cached so the player-history lookup is O(1).
let nameIndex: Map<string, { tournament: string; entry: OwnershipEntry }[]> | null = null;
function ensureIndex() {
  if (nameIndex) return nameIndex;
  nameIndex = new Map();
  for (const [tournament, data] of Object.entries(OWNERSHIP_DATA)) {
    for (const entry of data.players) {
      const key = normalizeName(entry.name);
      const arr = nameIndex.get(key) ?? [];
      arr.push({ tournament, entry });
      nameIndex.set(key, arr);
    }
  }
  return nameIndex;
}

export function listTournaments(): { name: string; meta: OwnershipMeta; count: number }[] {
  return TOURNAMENT_ORDER.filter((t) => OWNERSHIP_DATA[t]).map((t) => ({
    name: t,
    meta: OWNERSHIP_DATA[t].meta,
    count: OWNERSHIP_DATA[t].players.length,
  }));
}

export function getTournament(name: string): TournamentOwnership | null {
  return OWNERSHIP_DATA[name] ?? null;
}

export function getPlayerHistory(name: string): PlayerHistory | null {
  const idx = ensureIndex();
  const rows = idx.get(normalizeName(name));
  if (!rows || rows.length === 0) return null;
  const history = rows
    .map((r) => ({ tournament: r.tournament, own: r.entry.own, salary: r.entry.salary }))
    .sort((a, b) => {
      const ai = TOURNAMENT_ORDER.indexOf(a.tournament);
      const bi = TOURNAMENT_ORDER.indexOf(b.tournament);
      return ai - bi;
    });
  const owns = history.map((h) => h.own);
  const salaries = history.map((h) => h.salary);
  return {
    name: rows[0].entry.name,
    appearances: history.length,
    avgOwn: avg(owns),
    minOwn: Math.min(...owns),
    maxOwn: Math.max(...owns),
    avgSalary: avg(salaries),
    history,
  };
}

export function listPlayers(): PlayerHistory[] {
  const idx = ensureIndex();
  const out: PlayerHistory[] = [];
  for (const key of idx.keys()) {
    const h = getPlayerHistory(key);
    if (h) out.push(h);
  }
  return out.sort((a, b) => b.avgOwn - a.avgOwn);
}

// Leverage score: salary-adjusted ownership delta from the field median.
// Negative = under-owned for the price tier ("good leverage"), positive =
// chalk. Inputs: a tournament + a target ownership figure from another
// source (current projection). If you only have history, pass the player's
// avgOwn as `projected` to surface chronically under-owned price tiers.
export function leverage(
  tournament: string,
  player: string,
  projected: number,
): number | null {
  const t = getTournament(tournament);
  if (!t) return null;
  const target = t.players.find((p) => normalizeName(p.name) === normalizeName(player));
  if (!target) return null;
  // Median ownership among players within ±$300 salary band.
  const peers = t.players
    .filter((p) => Math.abs(p.salary - target.salary) <= 300)
    .map((p) => p.own);
  if (peers.length === 0) return null;
  const med = median(peers);
  return projected - med;
}

// Group all tournaments by their course. Useful when the same venue has
// multiple events in the dataset over time (Pebble, Torrey, etc.) — the
// course-level view aggregates ownership across every appearance.
export type CourseHistory = {
  course: string;
  events: { tournament: string; meta: OwnershipMeta }[];
  playerStats: {
    name: string;
    appearances: number;
    avgOwn: number;
    avgSalary: number;
    maxOwn: number;
    minOwn: number;
  }[];
};

export function listCourses(): { course: string; eventCount: number; meta: OwnershipMeta }[] {
  const map = new Map<string, { events: number; meta: OwnershipMeta }>();
  for (const t of Object.values(OWNERSHIP_DATA)) {
    const existing = map.get(t.meta.course);
    if (existing) existing.events++;
    else map.set(t.meta.course, { events: 1, meta: t.meta });
  }
  return [...map.entries()]
    .map(([course, v]) => ({ course, eventCount: v.events, meta: v.meta }))
    .sort((a, b) => b.eventCount - a.eventCount || a.course.localeCompare(b.course));
}

export function getCourseHistory(course: string): CourseHistory | null {
  const events: { tournament: string; meta: OwnershipMeta }[] = [];
  const perPlayer = new Map<string, { displayName: string; owns: number[]; salaries: number[] }>();

  for (const tName of TOURNAMENT_ORDER) {
    const t = OWNERSHIP_DATA[tName];
    if (!t || t.meta.course !== course) continue;
    events.push({ tournament: tName, meta: t.meta });
    for (const p of t.players) {
      const key = normalizeName(p.name);
      const row = perPlayer.get(key) ?? { displayName: p.name, owns: [], salaries: [] };
      row.owns.push(p.own);
      row.salaries.push(p.salary);
      perPlayer.set(key, row);
    }
  }
  if (events.length === 0) return null;

  const playerStats = [...perPlayer.values()]
    .map((r) => ({
      name: r.displayName,
      appearances: r.owns.length,
      avgOwn: avg(r.owns),
      avgSalary: avg(r.salaries),
      maxOwn: Math.max(...r.owns),
      minOwn: Math.min(...r.owns),
    }))
    .sort((a, b) => b.avgOwn - a.avgOwn);

  return { course, events, playerStats };
}

function avg(xs: number[]): number {
  return xs.reduce((a, b) => a + b, 0) / xs.length;
}

function median(xs: number[]): number {
  const sorted = [...xs].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}
